            "✿︎━━━━━━━━━━━━━━━━━━━━✿\n\n"
            "💡 Sᴇʟᴇᴄᴛ A Mᴏᴅᴜʟᴇ Fʀᴏᴍ Tʜᴇ Mᴇɴᴜ Bᴇʟᴏᴡ 👇",
            parse_mode=ParseMode.MARKDOWN,
